// RefundFilter provides filtering for Refund queries
type RefundFilter struct {
	Id                  *UUIDFilter
	AmountCents         *Int64Filter
	Reason              *StringFilter
	PaymentsDue         *Int64Filter
	PaymentsAuthorized  *Int64Filter
	PaymentsCaptured    *Int64Filter
	PaymentsRefunded    *Int64Filter
	PaymentsOutstanding *Int64Filter
	PaymentsOverpaid    *Int64Filter
	PaymentsCurrency    *StringFilter
	PaymentsState       *StringFilter
	Status              *StringFilter
	StatusEnteredAt     *DateTimeFilter
	Version             *Int64Filter
	// OrderID allows filtering by foreign key
	OrderID *UUIDFilter
	// Order keeps the rows whose order is among the Order rows
	// the filter finds (D90): one condition, the foreign key in the keys of
	// those rows.
	Order *OrderFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []RefundFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []RefundFilter
}

// RefundUpdate provides fields that can be updated
type RefundUpdate struct {
	AmountCents *types.GenericInt64
	Reason      *string
	// OrderID allows updating the foreign key for order
	OrderID *types.IdentityUUID
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewRefundSnapshotUpdate maps every mutable field from a complete
// Refund value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewRefundSnapshotUpdate(input *types.Refund) *RefundUpdate {
	update := &RefundUpdate{}
	if input == nil {
		return update
	}
	update.AmountCents = &input.AmountCents
	update.Reason = &input.Reason
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *RefundUpdate) ApplyTo(row *types.Refund) {
	if u == nil || row == nil {
		return
	}
	if u.AmountCents != nil {
		row.AmountCents = *u.AmountCents
	}
	if u.Reason != nil {
		row.Reason = *u.Reason
	}
	if u.OrderID != nil {
		row.Order.Id = u.OrderID
	}
}

// RefundFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func RefundFilterConditions(filter *RefundFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a RefundFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *RefundFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

